//! Ordinary HTML name producers preserve exact native DOMString values.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=subject name=seed></div><span id=literal name='A�z'></span><div id=mount></div><input id=control name=keep type=radio checked><slot id=slot name=keep></slot><svg><g id=foreign name=keep></g></svg></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){assert_eq!(p.console_eval(d,f,s).errors,0,"{}",p.report());}
#[test]
fn passive_name_domstring_all_public_attribute_producers_update_exact_live_filters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('subject'),previous=document.getElementsByName('seed');for(var mode=0;mode<7;mode++){var value='A\ud800z'+mode;if(mode===0)subject.setAttribute('name',value);else if(mode===1)subject.setAttributeNS(null,'name',value);else if(mode<5){var attr=subject.getAttributeNode('name');if(mode===2)attr.value=value;else if(mode===3)attr.nodeValue=value;else attr.textContent=value;}else{var attr=document.createAttribute('name');attr.value=value;if(mode===5)subject.setAttributeNode(attr);else subject.setAttributeNodeNS(attr);if(attr.ownerElement!==subject)throw 'incoming Attr identity';}var current=document.getElementsByName(value);if(previous.length!==0||current.length!==1||current[0]!==subject||current.item(0)!==subject||subject.getAttribute('name')!==value||subject.getAttributeNS(null,'name')!==value||subject.getAttributeNode('name').value!==value||document.getElementsByName('A�z'+mode).length!==0)throw 'exact public name';previous=current;}
"#);}
#[test]
fn passive_name_domstring_clone_move_remove_and_observation_use_actual_names(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('subject'),mount=document.getElementById('mount'),literal=document.getElementById('literal'),observer=new MutationObserver(function(){});observer.observe(subject,{attributes:true,attributeOldValue:true,attributeFilter:['name']});subject.setAttribute('name','A\ud800z');var attr=subject.getAttributeNode('name'),list=document.getElementsByName('A\ud800z');if(document.getElementsByName('A�z').length!==1||document.getElementsByName('A�z')[0]!==literal)throw 'projection alias excluded';var copy=subject.cloneNode(true);copy.removeAttribute('id');mount.appendChild(copy);if(copy===subject||copy.getAttributeNode('name')===attr||list.length!==2||list[0]!==subject||list[1]!==copy||document.getElementsByTagName('div').namedItem('A\ud800z')!==subject)throw 'cloned native names and collection';mount.appendChild(subject);if(list[0]!==copy||list[1]!==subject)throw 'current moved order';attr.value='A\udfffz';if(list.length!==1||list[0]!==copy||document.getElementsByName('A\udfffz')[0]!==subject)throw 'Attr mutation exactness';subject.removeAttribute('name');if(attr.ownerElement!==null||attr.value!=='A\udfffz'||document.getElementsByName('A\udfffz').length!==0)throw 'detached Attr and removed filter';var records=observer.takeRecords();if(records.length!==3||records[0].oldValue!=='seed'||records[1].oldValue!=='A\ud800z'||records[2].oldValue!=='A\udfffz')throw 'actual observation values';
"#);}
#[test]
fn passive_name_domstring_once_conversion_and_abrupt_author_effects_are_preserved(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('subject'),input=document.getElementById('control'),calls=0;subject.setAttribute('name',{toString:function(){calls++;input.value='converted';return 'A\ud800z';}});if(calls!==1||input.value!=='converted'||document.getElementsByName('A\ud800z')[0]!==subject)throw 'converted once';var marker={};try{subject.setAttribute('name',{toString:function(){calls++;input.value='effect';throw marker;}});throw 'missing abrupt';}catch(e){if(e!==marker)throw e;}if(calls!==2||input.value!=='effect'||subject.getAttribute('name')!=='A\ud800z')throw 'abrupt author effects';
"#);}

#[test]
fn passive_name_domstring_control_slot_frame_foreign_namespace_and_import_guards_preserve_native_state(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var subject=document.getElementById('subject'),control=document.getElementById('control'),slot=document.getElementById('slot'),foreign=document.getElementById('foreign'),frame=document.createElement('iframe'),incoming=document.createAttribute('name');incoming.value='A\ud800z';var inert=document.implementation.createHTMLDocument('inert'),source=inert.createElement('input');source.setAttribute('name','A\ud800z');inert.body.appendChild(source);"#);run(&mut d,&mut f,&mut p,r#"var savedControlName=control.getAttributeNode('name');control.setAttribute('name','A\ud800z');if(control.name!=='A\ud800z'||!control.checked)throw 'native radio raw name';control.setAttributeNode(incoming);if(control.name!=='A\ud800z'||incoming.ownerElement!==control||!control.checked)throw 'native radio Attr name';control.setAttributeNode(savedControlName);control.name='keep';if(incoming.ownerElement!==null||control.name!=='keep'||!control.checked)throw 'radio name restoration';var imported=document.importNode(source,true);if(imported.name!=='A\ud800z'||imported.ownerDocument!==document||imported.parentNode!==null)throw 'native imported raw input name';"#);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());
 for source in [r#"slot.setAttribute('name','A\ud800z');"#,r#"frame.setAttribute('name','A\ud800z');"#,r#"foreign.setAttribute('name','A\ud800z');"#,r#"subject.setAttributeNS('urn:attr','name','A\ud800z');"#]{p.begin_job();assert!(p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"{source}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);}
 run(&mut d,&mut f,&mut p,r#"if(incoming.ownerElement!==null||control.name!=='keep'||!control.checked||slot.getAttribute('name')!=='keep'||foreign.getAttribute('name')!=='keep'||frame.getAttribute('name')!==null||subject.getAttributeNS('urn:attr','name')!==null)throw 'guard publication';subject.setAttribute('name','fresh\ud800');if(document.getElementsByName('fresh\ud800')[0]!==subject)throw 'ordinary recovery';"#);
}
#[test]
fn passive_name_domstring_resource_refusal_is_atomic_and_recovers(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var p=document.getElementById('subject'),a=p.getAttributeNode('name'),o=new MutationObserver(function(){});o.observe(p,{attributes:true,attributeOldValue:true,attributeFilter:['name']});");page.state.rebuild(&doc).unwrap();let before=format!("{:?}",doc.nodes);let commits=page.state.dom_commits;let retained=page.state.retained;let limit=page.state.retained_limit;let strings=page.state.limits.host.string_bytes;
 for mode in 0..4{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,2=>page.state.retained_limit=retained,_=>page.state.limits.host.string_bytes=4};let error=page.runtime.execute(r#"p.setAttribute('name','long A\ud800z');"#,&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound"),"{error}");assert_eq!(format!("{:?}",doc.nodes),before);assert_eq!(page.state.dom_commits,commits);assert_eq!(page.state.retained,retained);page.state.retained_limit=limit;page.state.limits.host.string_bytes=strings;}
 page.begin_job();run(&mut doc,&mut forms,&mut page,r#"if(a.value!=='seed'||o.takeRecords().length!==0)throw 'refusal publication';p.setAttribute('name','fresh A\ud800z');var r=o.takeRecords();if(a.value!==p.getAttribute('name')||r.length!==1||r[0].oldValue!=='seed'||document.getElementsByName(a.value)[0]!==p)throw 'fresh raw recovery';"#);
}
#[test]
fn passive_name_domstring_retained_storage_tracks_actual_raw_attribute_backing(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,"var p=document.getElementById('subject');");page.state.rebuild(&doc).unwrap();let n=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("subject")).unwrap();
 for source in [r#"p.setAttribute('name','long A\ud800z');"#,"p.setAttribute('name','short');",r#"p.setAttribute('name','B\udfffz');"#,"p.setAttribute('name','');"]{let before=page.state.retained;let old=doc.dom_attr(n,"name").unwrap().capacity();run(&mut doc,&mut forms,&mut page,source);assert_eq!(page.state.retained,before-old+doc.dom_attr(n,"name").unwrap().capacity());}
}
